// GENERATED BY GAMEX ENGINE — edit via the studio or the gamex CLI
//
// Reference interpreter for gamex/game-model.json. Zero dependencies; runs with plain `node` (≥ 22.18,
// native TypeScript type stripping). It is the executable definition of the rules: a backend is correct when
// it produces the same `then` as this file for every golden case in ../golden/.
//
// Semantics (see the Spec Pack README): checks run in order — preconditions, rules, placement eligibility,
// costs — and the first failure decides the error code. All effects of a step are evaluated against the
// state before the step and applied together. Limits, caps and cooldowns are counters/timestamps + rules.

export type Value = number | boolean | string;
type Values = Record<string, Value>;

// ---------------------------------------------------------------------------------------------- model types

interface Provenance {
  status: string;
}
interface Effect {
  op: 'set' | 'add' | 'sub';
  target: string;
  value: string;
}
interface Limit {
  max: string;
  per: 'mission' | 'session' | 'day' | 'lifetime';
  errorCode?: string;
}
interface Action {
  id: string;
  preconditions: string[];
  costs: { resource: string; amount: string }[];
  effects: Effect[];
  cooldown?: { seconds: string; errorCode?: string };
  limits?: Limit[];
  outcomes?: { id: string; weight: string; effects: Effect[] }[];
  errorCode: string;
  provenance: Provenance;
}
interface Placement {
  id: string;
  format: string;
  trigger: { action?: string; state?: string };
  eligibility: string[];
  caps?: Limit[];
  cooldownSeconds?: string;
  reward?: Effect[];
  onShow?: Effect[];
  forbiddenIn?: string[];
  inWorld?: boolean;
  provenance: Provenance;
}
interface Rule {
  id: string;
  appliesTo: { actions?: string[]; placements?: string[] };
  expr: string;
  severity: 'blocking' | 'warning';
  errorCode: string;
}
export interface GameModel {
  constants: { id: string; value: number | Curve }[];
  variables: { id: string; type: string; scope: string; initial: Value }[];
  resources: { id: string; starting: number; cap?: number }[];
  actions: Action[];
  rules: Rule[];
  monetization: { placements: Placement[]; forbiddenStates: string[] };
}
export type Curve =
  | {
      type: 'linear';
      params: { base: number; perStep: number; from?: number };
      rounding?: Rounding;
      min?: number;
      max?: number;
    }
  | {
      type: 'geometric';
      params: { base: number; ratio: number; from?: number };
      rounding?: Rounding;
      min?: number;
      max?: number;
    }
  | {
      type: 'table';
      params: { values: number[]; from?: number };
      rounding?: Rounding;
      min?: number;
      max?: number;
    }
  | {
      type: 'piecewise';
      params: { segments: { upTo?: number; curve: Curve }[] };
      rounding?: Rounding;
      min?: number;
      max?: number;
    };
type Rounding = 'none' | 'floor' | 'ceil' | 'round-half-even';

export class RuleError extends Error {}

// ------------------------------------------------------------------------------------------------ helpers

export function idToKey(id: string): string {
  return id.replace(/-([a-z0-9])/g, (_m: string, ch: string) => ch.toUpperCase());
}
const refId = (ref: string): string => ref.slice(ref.indexOf(':') + 1);
const constCase = (id: string): string => id.toUpperCase().replaceAll('-', '_');

export function roundHalfEven(x: number): number {
  const floor = Math.floor(x);
  const diff = x - floor;
  if (diff < 0.5) return floor;
  if (diff > 0.5) return floor + 1;
  return floor % 2 === 0 ? floor : floor + 1;
}

/** x^k by exponentiation by squaring (identical float operations to the engine). */
export function integerPower(x: number, k: number): number {
  let base = k < 0 ? 1 / x : x;
  let e = Math.abs(k);
  let result = 1;
  while (e > 0) {
    if (e % 2 === 1) result *= base;
    base *= base;
    e = Math.floor(e / 2);
  }
  return result;
}

export function evalCurve(curve: Curve, n: number): number {
  if (!Number.isInteger(n)) throw new RuleError(`curve tier must be an integer, got ${String(n)}`);
  let v: number;
  switch (curve.type) {
    case 'linear':
      v = curve.params.base + curve.params.perStep * (n - (curve.params.from ?? 1));
      break;
    case 'geometric':
      v = curve.params.base * integerPower(curve.params.ratio, n - (curve.params.from ?? 1));
      break;
    case 'table': {
      const values = curve.params.values;
      v = values[Math.min(Math.max(n - (curve.params.from ?? 1), 0), values.length - 1)] ?? 0;
      break;
    }
    case 'piecewise': {
      const seg = curve.params.segments.find((s) => s.upTo === undefined || n <= s.upTo);
      if (seg === undefined) throw new RuleError(`no curve segment for ${String(n)}`);
      v = evalCurve(seg.curve, n);
      break;
    }
  }
  const r = curve.rounding ?? 'none';
  if (r === 'floor') v = Math.floor(v);
  else if (r === 'ceil') v = Math.ceil(v);
  else if (r === 'round-half-even') v = roundHalfEven(v);
  if (curve.min !== undefined) v = Math.max(v, curve.min);
  if (curve.max !== undefined) v = Math.min(v, curve.max);
  if (!Number.isFinite(v)) throw new RuleError('curve value is not finite');
  return v;
}

// ------------------------------------------------------------------------------------- expression language

type Node =
  | { k: 'lit'; v: Value }
  | { k: 'id'; name: string }
  | { k: 'un'; op: string; a: Node }
  | { k: 'bin'; op: string; a: Node; b: Node }
  | { k: 'if'; c: Node; t: Node; e: Node }
  | { k: 'call'; f: string; args: Node[] };

const PREC: Record<string, number> = {
  '||': 2,
  '&&': 3,
  '==': 4,
  '!=': 4,
  '<': 5,
  '<=': 5,
  '>': 5,
  '>=': 5,
  '+': 6,
  '-': 6,
  '*': 7,
  '/': 7,
  '%': 7,
};
const PUNCT = [
  '<=',
  '>=',
  '==',
  '!=',
  '&&',
  '||',
  '(',
  ')',
  ',',
  '?',
  ':',
  '!',
  '-',
  '+',
  '*',
  '/',
  '%',
  '<',
  '>',
];

function tokenize(src: string): { t: string; v?: Value }[] {
  const out: { t: string; v?: Value }[] = [];
  let i = 0;
  while (i < src.length) {
    const ch = src.charAt(i);
    if (' \t\n\r'.includes(ch)) {
      i++;
      continue;
    }
    const num = /^\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/.exec(src.slice(i));
    if (num !== null) {
      out.push({ t: 'lit', v: Number(num[0]) });
      i += num[0].length;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < src.length && src.charAt(j) !== '"') j += src.charAt(j) === '\\' ? 2 : 1;
      out.push({ t: 'lit', v: JSON.parse(src.slice(i, j + 1)) as string });
      i = j + 1;
      continue;
    }
    const id = /^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*/.exec(src.slice(i));
    if (id !== null) {
      out.push(
        id[0] === 'true' || id[0] === 'false'
          ? { t: 'lit', v: id[0] === 'true' }
          : { t: 'id', v: id[0] },
      );
      i += id[0].length;
      continue;
    }
    const p = PUNCT.find((x) => src.startsWith(x, i));
    if (p === undefined) throw new RuleError(`unexpected "${ch}" in ${src}`);
    out.push({ t: p });
    i += p.length;
  }
  return out;
}

const parsed = new Map<string, Node>();

export function parse(src: string): Node {
  const cached = parsed.get(src);
  if (cached !== undefined) return cached;
  const toks = tokenize(src);
  let i = 0;
  const peek = (): string => toks[i]?.t ?? 'eof';
  const expect = (t: string): void => {
    if (peek() !== t) throw new RuleError(`expected ${t} in ${src}`);
    i++;
  };
  const expr = (min: number): Node => {
    let left = prefix();
    for (;;) {
      const t = peek();
      if (t === '?' && min <= 1) {
        i++;
        const then = expr(1);
        expect(':');
        left = { k: 'if', c: left, t: then, e: expr(1) };
        continue;
      }
      const p = PREC[t];
      if (p === undefined || p < min) return left;
      i++;
      left = { k: 'bin', op: t, a: left, b: expr(p + 1) };
    }
  };
  const prefix = (): Node => {
    const tok = toks[i++];
    if (tok === undefined) throw new RuleError(`unexpected end of ${src}`);
    if (tok.t === 'lit') return { k: 'lit', v: tok.v as Value };
    if (tok.t === 'id') {
      if (peek() !== '(') return { k: 'id', name: tok.v as string };
      i++;
      const args: Node[] = [];
      if (peek() !== ')') {
        args.push(expr(1));
        while (peek() === ',') {
          i++;
          args.push(expr(1));
        }
      }
      expect(')');
      return { k: 'call', f: tok.v as string, args };
    }
    if (tok.t === '(') {
      const inner = expr(1);
      expect(')');
      return inner;
    }
    if (tok.t === '!' || tok.t === '-') return { k: 'un', op: tok.t, a: expr(8) };
    throw new RuleError(`unexpected "${tok.t}" in ${src}`);
  };
  const node = expr(1);
  if (i !== toks.length) throw new RuleError(`trailing tokens in ${src}`);
  parsed.set(src, node);
  return node;
}

export interface Env {
  value(name: string): Value | undefined;
  curve(name: string, n: number): number;
  eligible(id: string): boolean;
}

function num(v: Value): number {
  if (typeof v !== 'number') throw new RuleError(`expected a number, got ${JSON.stringify(v)}`);
  return v;
}
function bool(v: Value): boolean {
  if (typeof v !== 'boolean') throw new RuleError(`expected a boolean, got ${JSON.stringify(v)}`);
  return v;
}
function finite(x: number): number {
  if (!Number.isFinite(x)) throw new RuleError('result is not finite');
  return x;
}

export function evaluate(node: Node, env: Env): Value {
  switch (node.k) {
    case 'lit':
      return node.v;
    case 'id': {
      const v = env.value(node.name);
      if (v === undefined) throw new RuleError(`unknown name ${node.name}`);
      return v;
    }
    case 'un':
      return node.op === '!' ? !bool(evaluate(node.a, env)) : -num(evaluate(node.a, env));
    case 'if':
      return bool(evaluate(node.c, env)) ? evaluate(node.t, env) : evaluate(node.e, env);
    case 'call': {
      if (node.f === 'curve') {
        const a = node.args[0];
        if (a?.k !== 'id' || node.args[1] === undefined) throw new RuleError('curve(name, n)');
        return env.curve(a.name, num(evaluate(node.args[1], env)));
      }
      if (node.f === 'eligible') {
        const a = node.args[0];
        if (a?.k !== 'lit' || typeof a.v !== 'string') throw new RuleError('eligible("id")');
        return env.eligible(a.v);
      }
      const xs = node.args.map((a) => num(evaluate(a, env)));
      switch (node.f) {
        case 'min':
          return Math.min(...xs);
        case 'max':
          return Math.max(...xs);
        case 'clamp':
          return Math.min(Math.max(xs[0] ?? 0, xs[1] ?? 0), xs[2] ?? 0);
        case 'abs':
          return Math.abs(xs[0] ?? 0);
        case 'floor':
          return Math.floor(xs[0] ?? 0);
        case 'ceil':
          return Math.ceil(xs[0] ?? 0);
        case 'round':
          return roundHalfEven(xs[0] ?? 0);
        default:
          throw new RuleError(`unknown function ${node.f}`);
      }
    }
    case 'bin': {
      const { op } = node;
      if (op === '&&') return bool(evaluate(node.a, env)) && bool(evaluate(node.b, env));
      if (op === '||') return bool(evaluate(node.a, env)) || bool(evaluate(node.b, env));
      if (op === '==') return evaluate(node.a, env) === evaluate(node.b, env);
      if (op === '!=') return evaluate(node.a, env) !== evaluate(node.b, env);
      const a = num(evaluate(node.a, env));
      const b = num(evaluate(node.b, env));
      switch (op) {
        case '<':
          return a < b;
        case '<=':
          return a <= b;
        case '>':
          return a > b;
        case '>=':
          return a >= b;
        case '+':
          return finite(a + b);
        case '-':
          return finite(a - b);
        case '*':
          return finite(a * b);
        default:
          if (b === 0) throw new RuleError('division by zero');
          return finite(op === '/' ? a / b : a % b);
      }
    }
  }
}

// --------------------------------------------------------------------------- limits, caps and cooldowns

/** "Never" for last-used timestamps. */
export const NEVER = -1e12;

interface Compiled {
  constants: Map<string, number>;
  curves: Map<string, Curve>;
  types: Map<string, string>;
  caps: Map<string, number | undefined>;
  resources: Set<string>;
  initial: Values;
  actions: Map<string, { a: Action; effects: Effect[]; rules: Rule[]; placements: string[] }>;
  placements: Map<
    string,
    { p: Placement; onShow: Effect[]; rules: Rule[]; forbidden: Set<string> }
  >;
}

const compiledModels = new WeakMap<GameModel, Compiled>();

/** Turns limits, caps and cooldowns into counters, timestamps, rules and effects (as the engine does). */
export function compile(model: GameModel): Compiled {
  const hit = compiledModels.get(model);
  if (hit !== undefined) return hit;
  const variables = [...model.variables];
  const rules: (Rule & { origin?: string })[] = [...model.rules];
  const extraEffects = new Map<string, Effect[]>();
  const scopeOf = { mission: 'mission', session: 'session', day: 'day', lifetime: 'player' };
  const limited: {
    kind: string;
    id: string;
    limits: Limit[];
    cooldown: { seconds: string; errorCode?: string } | undefined;
  }[] = [
    ...model.actions.map((a) => ({
      kind: 'action',
      id: a.id,
      limits: a.limits ?? [],
      cooldown: a.cooldown,
    })),
    ...model.monetization.placements.map((p) => ({
      kind: 'placement',
      id: p.id,
      limits: p.caps ?? [],
      cooldown: p.cooldownSeconds === undefined ? undefined : { seconds: p.cooldownSeconds },
    })),
  ];
  for (const n of limited) {
    const effects: Effect[] = [];
    const appliesTo =
      n.kind === 'action' ? { actions: [`action:${n.id}`] } : { placements: [`placement:${n.id}`] };
    const scopes = new Set<string>();
    const used = new Set<string>();
    n.limits.forEach((limit, j) => {
      const counter = `${n.id}-count-${limit.per}`;
      if (!scopes.has(limit.per)) {
        scopes.add(limit.per);
        if (!variables.some((v) => v.id === counter))
          variables.push({ id: counter, type: 'int', scope: scopeOf[limit.per], initial: 0 });
        effects.push({ op: 'add', target: `var:${counter}`, value: '1' });
      }
      let ruleId = `${n.id}-limit-${limit.per}`;
      if (used.has(ruleId)) ruleId = `${ruleId}-${String(j)}`;
      used.add(ruleId);
      if (!rules.some((r) => r.id === ruleId)) {
        rules.push({
          id: ruleId,
          appliesTo,
          expr: `${idToKey(counter)} < (${limit.max})`,
          severity: 'blocking',
          errorCode: limit.errorCode ?? `${constCase(n.id)}_LIMIT_REACHED`,
        });
      }
    });
    if (n.cooldown !== undefined) {
      const lastAt = `${n.id}-last-at`;
      if (!variables.some((v) => v.id === lastAt))
        variables.push({ id: lastAt, type: 'timestamp', scope: 'player', initial: NEVER });
      if (!rules.some((r) => r.id === `${n.id}-cooldown`)) {
        rules.push({
          id: `${n.id}-cooldown`,
          appliesTo,
          expr: `now - ${idToKey(lastAt)} >= (${n.cooldown.seconds})`,
          severity: 'blocking',
          errorCode: n.cooldown.errorCode ?? `${constCase(n.id)}_COOLDOWN_ACTIVE`,
        });
      }
      effects.push({ op: 'set', target: `var:${lastAt}`, value: 'now' });
    }
    extraEffects.set(`${n.kind}:${n.id}`, effects);
  }
  const withExtra = (list: Effect[] | undefined, extra: Effect[] | undefined): Effect[] => {
    const out = [...(list ?? [])];
    for (const e of extra ?? [])
      if (!out.some((x) => x.op === e.op && x.target === e.target && x.value === e.value))
        out.push(e);
    return out;
  };

  const constants = new Map<string, number>();
  const curves = new Map<string, Curve>();
  for (const k of model.constants) {
    if (typeof k.value === 'number') constants.set(idToKey(k.id), k.value);
    else curves.set(idToKey(k.id), k.value);
  }
  const types = new Map<string, string>();
  const initial: Values = {};
  for (const v of variables) {
    types.set(idToKey(v.id), v.type);
    initial[idToKey(v.id)] = v.initial;
  }
  const caps = new Map<string, number | undefined>();
  for (const r of model.resources) {
    caps.set(idToKey(r.id), r.cap);
    initial[idToKey(r.id)] = r.starting;
  }
  const rulesFor = (kind: 'actions' | 'placements', ref: string): Rule[] =>
    rules.filter((r) => r.appliesTo[kind]?.includes(ref) === true);
  const forbiddenGlobal = model.monetization.forbiddenStates.map(refId);
  const placements = new Map(
    model.monetization.placements.map((p) => [
      p.id,
      {
        p,
        onShow: withExtra(p.onShow, extraEffects.get(`placement:${p.id}`)),
        rules: rulesFor('placements', `placement:${p.id}`),
        forbidden: new Set([...forbiddenGlobal, ...(p.forbiddenIn ?? []).map(refId)]),
      },
    ]),
  );
  const actions = new Map(
    model.actions.map((a) => [
      a.id,
      {
        a,
        effects: withExtra(a.effects, extraEffects.get(`action:${a.id}`)),
        rules: rulesFor('actions', `action:${a.id}`),
        placements: model.monetization.placements
          .filter((p) => p.trigger.action === `action:${a.id}`)
          .map((p) => p.id),
      },
    ]),
  );
  const c: Compiled = {
    constants,
    curves,
    types,
    caps,
    resources: new Set(caps.keys()),
    initial,
    actions,
    placements,
  };
  compiledModels.set(model, c);
  return c;
}

// ------------------------------------------------------------------------------------------- the rules

export interface World {
  state: string;
  prevState: string;
  now: number;
  values: Values;
  persona: { skill: number; churnSensitivity: number };
}

/** A world from a golden case's `given`: initial values overridden by `given.vars`. */
export function worldFrom(
  model: GameModel,
  given: {
    state: string;
    prevState?: string;
    now?: number;
    persona?: { skill?: number; churnSensitivity?: number };
    vars?: Values;
  },
): World {
  const c = compile(model);
  return {
    state: given.state,
    prevState: given.prevState ?? given.state,
    now: given.now ?? 0,
    values: { ...c.initial, ...given.vars },
    persona: {
      skill: given.persona?.skill ?? 0.5,
      churnSensitivity: given.persona?.churnSensitivity ?? 0.5,
    },
  };
}

function envOf(model: GameModel, w: World): Env {
  const c = compile(model);
  const builtins: Record<string, Value> = {
    now: w.now,
    state: w.state,
    prevState: w.prevState,
    'persona.skill': w.persona.skill,
    'persona.churnSensitivity': w.persona.churnSensitivity,
  };
  return {
    value: (name) => w.values[name] ?? c.constants.get(name) ?? builtins[name],
    curve: (name, n) => {
      const curve = c.curves.get(name);
      if (curve === undefined) throw new RuleError(`unknown curve ${name}`);
      return evalCurve(curve, n);
    },
    eligible: (id) => placementEligibility(model, w, id).eligible,
  };
}

const truth = (model: GameModel, w: World, src: string): boolean =>
  bool(evaluate(parse(src), envOf(model, w)));
const amount = (model: GameModel, w: World, src: string): number =>
  num(evaluate(parse(src), envOf(model, w)));

/** Whether a placement may be shown now, and if not, why. */
export function placementEligibility(
  model: GameModel,
  w: World,
  placementId: string,
): { eligible: boolean; reason?: string } {
  const entry = compile(model).placements.get(placementId);
  if (entry === undefined) throw new RuleError(`unknown placement ${placementId}`);
  const { p, rules, forbidden } = entry;
  const trigger = p.trigger.state === undefined ? undefined : refId(p.trigger.state);
  if (
    p.inWorld !== true &&
    (forbidden.has(w.state) || (trigger !== undefined && forbidden.has(trigger)))
  )
    return { eligible: false, reason: 'forbidden-state' };
  for (const e of p.eligibility)
    if (!truth(model, w, e)) return { eligible: false, reason: `eligibility: ${e}` };
  for (const r of rules)
    if (r.severity === 'blocking' && !truth(model, w, r.expr))
      return { eligible: false, reason: `rule:${r.id}` };
  return { eligible: true };
}

export type Check = { ok: true } | { ok: false; error: string };

/** Whether an action may run; the first failing check decides the error code. */
export function checkAction(model: GameModel, w: World, actionId: string): Check {
  const entry = compile(model).actions.get(actionId);
  if (entry === undefined) throw new RuleError(`unknown action ${actionId}`);
  for (const p of entry.a.preconditions)
    if (!truth(model, w, p)) return { ok: false, error: entry.a.errorCode };
  for (const r of entry.rules)
    if (r.severity === 'blocking' && !truth(model, w, r.expr))
      return { ok: false, error: r.errorCode };
  for (const pid of entry.placements) {
    const e = placementEligibility(model, w, pid);
    if (!e.eligible) {
      const rule =
        e.reason?.startsWith('rule:') === true
          ? compile(model)
              .placements.get(pid)
              ?.rules.find((r) => `rule:${r.id}` === e.reason)
          : undefined;
      return { ok: false, error: rule?.errorCode ?? 'PLACEMENT_NOT_ELIGIBLE' };
    }
  }
  for (const cost of entry.a.costs) {
    const key = idToKey(refId(cost.resource));
    const have = w.values[key];
    if (typeof have !== 'number' || have < amount(model, w, cost.amount))
      return { ok: false, error: `INSUFFICIENT_${constCase(refId(cost.resource))}` };
  }
  return { ok: true };
}

export interface ActionResult {
  result: 'ok' | 'rejected';
  error?: string;
  outcome?: string;
  deltas: Values;
  impressions?: string[];
  next: World;
}

/** Runs an action. Actions with random outcomes need `outcome` (golden cases always give it). */
export function applyAction(
  model: GameModel,
  w: World,
  actionId: string,
  outcome?: string,
): ActionResult {
  const check = checkAction(model, w, actionId);
  if (!check.ok) return { result: 'rejected', error: check.error, deltas: {}, next: w };
  const c = compile(model);
  const entry = c.actions.get(actionId);
  if (entry === undefined) throw new RuleError(`unknown action ${actionId}`);
  const effects: Effect[] = [...entry.effects];
  if (entry.a.outcomes !== undefined) {
    const o = entry.a.outcomes.find((x) => x.id === outcome);
    if (o === undefined)
      throw new RuleError(
        `action ${actionId} needs one of the outcomes ${entry.a.outcomes.map((x) => x.id).join(', ')}`,
      );
    effects.push(...o.effects);
  }
  for (const pid of entry.placements) {
    const p = c.placements.get(pid);
    effects.push(...(p?.onShow ?? []), ...(p?.p.reward ?? []));
  }
  const env = envOf(model, w);
  const computed: { op: Effect['op']; key: string; value: Value }[] = [
    ...entry.a.costs.map((cost) => ({
      op: 'sub' as const,
      key: idToKey(refId(cost.resource)),
      value: amount(model, w, cost.amount),
    })),
    ...effects.map((e) => ({
      op: e.op,
      key: idToKey(refId(e.target)),
      value: evaluate(parse(e.value), env),
    })),
  ];
  const values: Values = { ...w.values };
  for (const e of computed) {
    const old = values[e.key];
    let next: Value =
      e.op === 'set'
        ? e.value
        : e.op === 'add'
          ? num(old as Value) + num(e.value)
          : num(old as Value) - num(e.value);
    if (typeof next === 'number') {
      const isResource = c.resources.has(e.key);
      if ((isResource || c.types.get(e.key) === 'int') && !Number.isInteger(next))
        throw new RuleError(`${e.key} must be a whole number`);
      if (isResource) {
        if (next < 0) next = 0;
        const cap = c.caps.get(e.key);
        if (cap !== undefined && next > cap) next = cap;
      }
    }
    values[e.key] = next;
  }
  const deltas: Values = {};
  for (const key of Object.keys(values).sort()) {
    const a = w.values[key];
    const b = values[key];
    if (a === b || b === undefined) continue;
    deltas[key] = typeof a === 'number' && typeof b === 'number' ? b - a : b;
  }
  return {
    result: 'ok',
    ...(outcome === undefined || entry.a.outcomes === undefined ? {} : { outcome }),
    deltas,
    ...(entry.placements.length === 0 ? {} : { impressions: [...entry.placements] }),
    next: { ...w, values },
  };
}
